public class JPrintDigitsReverse {
	public static void main(String[] args) {
		//Paso 1: Definir las variables que necesitamos para este programa
		int num = 1234;
		int lastDigit;
		//Paso 2: Imprimir los digitos del entero de derecha a izquierda
		do {
			//Paso 2.1: Obtener el ultimo digito del entero
			lastDigit = num % 10;
			//Paso 2.2: Imprimir el digito extraido
			System.out.println(lastDigit);
			//Paso 2.3: Eliminar el ultimo digito del entero
			num = num / 10;
		} while (num > 0);
	}
}

